#include "i18n.h"
#include <gio/gio.h>
#include <glib.h>

/* These symbols are generated by ld -r -b binary for the embedded catalogs. */
extern const unsigned char _binary_src_en_properties_start[];
extern const unsigned char _binary_src_en_properties_end[];
extern const unsigned char _binary_src_zh_CN_properties_start[];
extern const unsigned char _binary_src_zh_CN_properties_end[];

static GKeyFile *catalog;

void i18n_set_language(const char *language) {
  if (catalog) g_key_file_unref(catalog);
  catalog = g_key_file_new();
  const unsigned char *start;
  const unsigned char *end;
  if (language && g_strcmp0(language, "en") == 0) {
    start = _binary_src_en_properties_start;
    end = _binary_src_en_properties_end;
  } else {
    start = _binary_src_zh_CN_properties_start;
    end = _binary_src_zh_CN_properties_end;
  }
  g_key_file_load_from_data(catalog, (const gchar *)start, (gsize)(end - start),
                            G_KEY_FILE_NONE, NULL);
}

const char *i18n(const char *key) { static char *value; g_free(value); value = NULL; if (!catalog) i18n_set_language("zh-CN"); value = g_key_file_get_string(catalog, "strings", key, NULL); return value ? value : key; }
